-- Initial schema: users, refresh tokens, meetings, invitees.
-- Times are DATETIME(3) in UTC. Ids are UUID strings generated by the application.

CREATE TABLE users (
  id            CHAR(36)     NOT NULL PRIMARY KEY,
  email         VARCHAR(254) NOT NULL,
  display_name  VARCHAR(60)  NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  created_at    DATETIME(3)  NOT NULL,
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE refresh_tokens (
  id          CHAR(36)    NOT NULL PRIMARY KEY,
  user_id     CHAR(36)    NOT NULL,
  family_id   CHAR(36)    NOT NULL,
  token_hash  CHAR(64)    NOT NULL,
  expires_at  DATETIME(3) NOT NULL,
  revoked_at  DATETIME(3) NULL,
  created_at  DATETIME(3) NOT NULL,
  UNIQUE KEY uq_refresh_tokens_token_hash (token_hash),
  KEY ix_refresh_tokens_family (family_id),
  KEY ix_refresh_tokens_user (user_id),
  CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE meetings (
  id               CHAR(36)          NOT NULL PRIMARY KEY,
  host_id          CHAR(36)          NOT NULL,
  title            VARCHAR(120)      NOT NULL,
  description      VARCHAR(2000)     NULL,
  starts_at        DATETIME(3)       NOT NULL,
  duration_minutes SMALLINT UNSIGNED NOT NULL,
  call_type        ENUM('audio', 'video') NOT NULL,
  status           ENUM('scheduled', 'ended', 'cancelled') NOT NULL DEFAULT 'scheduled',
  created_at       DATETIME(3)       NOT NULL,
  updated_at       DATETIME(3)       NOT NULL,
  KEY ix_meetings_host_starts (host_id, starts_at),
  CONSTRAINT fk_meetings_host FOREIGN KEY (host_id) REFERENCES users (id),
  CONSTRAINT ck_meetings_duration CHECK (duration_minutes BETWEEN 5 AND 480)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE meeting_invitees (
  meeting_id CHAR(36)    NOT NULL,
  user_id    CHAR(36)    NOT NULL,
  created_at DATETIME(3) NOT NULL,
  PRIMARY KEY (meeting_id, user_id),
  KEY ix_meeting_invitees_user (user_id),
  CONSTRAINT fk_meeting_invitees_meeting FOREIGN KEY (meeting_id) REFERENCES meetings (id) ON DELETE CASCADE,
  CONSTRAINT fk_meeting_invitees_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
